frappe.ready(function() {
    const form = document.getElementById('form-suivi');
    const resultArea = document.getElementById('result-area');
    const errorDiv = document.getElementById('error-msg');
    const btn = document.getElementById('btn-rechercher');

    form.addEventListener('submit', async function(e) {
        e.preventDefault();

        const docName = document.getElementById('doc_name').value.trim();
        if (!docName) return;

        btn.innerText = 'Recherche en cours...';
        btn.disabled = true;
        resultArea.style.display = 'none';
        errorDiv.style.display = 'none';

        try {
            const resp = await fetch('/api/method/udshed.udshed.doctype.session_inscription_candidate.session_inscription_candidate.track_candidature', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-Frappe-CSRF-Token': frappe.csrf_token || ''
                },
                body: JSON.stringify({ doc_name: docName })
            });

            const data = await resp.json();

            if (data.message) {
                renderResult(data.message);
                resultArea.style.display = 'block';
            } else if (data._server_messages) {
                const msgs = JSON.parse(data._server_messages);
                errorDiv.innerText = msgs.map(m => JSON.parse(m).message).join(' ');
                errorDiv.style.display = 'block';
            }
        } catch(err) {
            errorDiv.innerText = 'Une erreur est survenue. Veuillez réessayer.';
            errorDiv.style.display = 'block';
        }

        btn.innerText = 'Rechercher';
        btn.disabled = false;
    });

    function renderResult(d) {
        document.getElementById('r-name').innerText = d.doc_name;
        document.getElementById('r-nom').innerText = d.last_name + ' ' + d.first_name;
        document.getElementById('r-niveau').innerText = d.niveau || '—';
        document.getElementById('r-filiere').innerText = d.filiere || '—';
        document.getElementById('r-centre').innerText = d.examination_centre || '—';
        document.getElementById('r-date').innerText = d.submitted_on;

        const badge = document.getElementById('r-status');
        badge.innerText = d.status;
        badge.className = 'status-badge status-' + d.status.replace(/\s+/g, '-').replace(/é/g, 'e').replace(/è/g, 'e');

        const steps = [
            { label: 'Candidature soumise', date: d.submitted_on },
            { label: 'Dossier en cours d\'examen', date: '' },
            { label: 'Décision', date: '' },
            { label: 'Inscription', date: '' }
        ];

        const statusOrder = ['En attente', 'Dossier en cours d\'examen', 'Accepté', 'Refusé', 'Inscrit'];
        const currentIdx = statusOrder.indexOf(d.status);

        if (currentIdx >= 1) steps[1].date = d.status_date;
        if (currentIdx >= 2) steps[2].date = d.status_date;
        if (currentIdx >= 3 && d.status === 'Inscrit') steps[3].date = d.status_date;

        const timeline = document.getElementById('timeline');
        timeline.innerHTML = '';
        steps.forEach(function(s, i) {
            const active = (d.status === 'Refusé') ? (i === 2) : (i <= currentIdx);
            timeline.innerHTML += '<div class="timeline-step"><div class="timeline-dot ' + (active ? 'active' : 'pending') + '"></div><div><div class="timeline-text">' + s.label + '</div>' + (s.date ? '<div class="timeline-date">' + s.date + '</div>' : '') + '</div></div>';
        });

        if (d.status_comment) {
            document.getElementById('comment-section').innerHTML = '<div style="margin-top:1rem;padding:12px 16px;background:#f5f6f8;border-radius:8px;font-size:13px;color:#3c3e44;"><strong>Observation :</strong> ' + d.status_comment + '</div>';
        } else {
            document.getElementById('comment-section').innerHTML = '';
        }
    }
});

