// Interception et envoi du formulaire final
document.getElementById('form-etape-3').addEventListener('submit', async function(e) {
    e.preventDefault();

    const btn = document.getElementById('btn-soumettre');
    btn.innerText = "Téléversement des pièces...";
    btn.disabled = true;

    try {
        // 1. Téléversements séquentiels vers Frappe
        const urlDiploma = await uploadFichierFrappe('access_diploma_copy');
        const urlBirth = await uploadFichierFrappe('birth_certificate');
        const urlPhoto = await uploadFichierFrappe('passport_photo');
        const urlMotivation = await uploadFichierFrappe('motivation_letter');
        const urlCV = await uploadFichierFrappe('cv');
        const urlReceipt = await uploadFichierFrappe('remittance_receipt');

        if (!urlDiploma || !urlBirth || !urlPhoto || !urlReceipt) {
            throw new Error('pièces obligatoires manquantes');
        }

        btn.innerText = "Traitement final...";

        // 2. Compilation des données locales (noms de champs du doctype)
        const payload = {
            doctype: "Session Inscription Candidate",
            last_name: localStorage.getItem('last_name') || '',
            first_name: localStorage.getItem('first_name') || '',
            email: localStorage.getItem('email') || '',
            phone: localStorage.getItem('phone') || '',
            birthdate: localStorage.getItem('date_of_birth') || '',
            birth_place: localStorage.getItem('place_of_birth') || '',
            sexe: localStorage.getItem('sexe') || '',
            niveau: localStorage.getItem('niveau') || '',
            examination_centre: localStorage.getItem('examination_centre') || '',
            access_diploma_copy: urlDiploma,
            birth_certificate: urlBirth,
            id_photo: urlPhoto,
            remittance_receipt: urlReceipt
        };

        // 3. Envoi à la base de données Frappe
        const response = await fetch('/api/resource/Session Inscription Candidate', {
            method: 'POST',
            headers: {
                'Accept': 'application/json',
                'Content-Type': 'application/json',
                'X-Frappe-CSRF-Token': frappe.csrf_token
            },
            body: JSON.stringify(payload)
        });

        const result = await response.json();

        // 4. Redirection forcée
        if (result.data) {
            localStorage.clear(); // Vider les caches locaux

            // Construit proprement l'adresse finale
            const targetUrl = "/success-candidature?name=" + encodeURIComponent(result.data.name) +
                              "&email=" + encodeURIComponent(payload.email) +
                              "&filiere=" + encodeURIComponent(payload.niveau) +
                              "&niveau=" + encodeURIComponent(payload.niveau);

            window.location.href = targetUrl;
        } else {
            alert("Erreur lors de la sauvegarde dans la base de données.");
            btn.innerText = "Soumettre ma candidature";
            btn.disabled = false;
        }
    } catch (err) {
        console.error(err);
        alert("Une erreur technique s'est produite lors du transfert.");
        btn.innerText = "Soumettre ma candidature";
        btn.disabled = false;
    }
});

