javascript:
frappe.ready(function() {
    frappe.call({
        method: 'udshed.udshed.doctype.session_inscription_candidate.session_inscription_candidate.get_session_status',
        callback: function(r) {
            if (!(r && r.message)) return;
            var badge = document.getElementById('session-badge');
            if (badge) {
                badge.innerText = r.message.label;
                var dot = badge.previousElementSibling;
                if (dot && dot.classList.contains('rounded-circle')) {
                    var colors = { open: '#28a745', closed: '#dc3545', draft: '#ffc107' };
                    dot.style.background = colors[r.message.css_class] || '#F08000';
                }
            }
            var bouton = document.getElementById('btn-deposer-candidature');
            if (!bouton) return;
            var ouverte = r.message.status === 'Open';
            bouton.classList.toggle('disabled', !ouverte);
            bouton.style.pointerEvents = ouverte ? '' : 'none';
            bouton.style.opacity = ouverte ? '' : '.6';
            bouton.style.cursor = ouverte ? '' : 'not-allowed';
            bouton.style.filter = ouverte ? '' : 'grayscale(.6)';
            bouton.title = ouverte ? '' : (r.message.label || 'Aucune session de candidature ouverte');
            if (!ouverte && !bouton.__bloque) {
                bouton.__bloque = true;
                bouton.addEventListener('click', function(e) {
                    e.preventDefault();
                    if (window.frappe && frappe.msgprint) {
                        frappe.msgprint({ title: 'Inscription indisponible', message: 'Les candidatures ne sont possibles que pendant une session de candidatures ouverte.\n\n' + (r.message.label || ''), indicator: 'orange' });
                    } else {
                        alert('Les candidatures ne sont possibles que pendant une session de candidatures ouverte.\n\n' + (r.message.label || ''));
                    }
                });
            }
        }
    });
});
